local config = {
  ui_story_5027_50270101_1_dialog_content = "Estamos finalmente aqui. Nosso destino está perto, né, PlayerName?",
  ui_story_5027_50270101_2_dialog_content = "Isso mesmo. Os subúrbios de Umbraton... tal como o seu informante sugeriu.\nEu posso sentir algo distorcido e maligno à espreita aqui.",
  ui_story_5027_50270101_3_dialog_content = "Hum... Luke, podemos realmente fazer isso apenas com nós dois?",
  ui_story_5027_50270101_4_dialog_content = "É a única maneira de manter um perfil baixo.",
  ui_story_5027_50270101_5_dialog_content = "Olhar. Há uma lua cheia esta noite. Você já ouviu falar daquele ditado que tem sido popular entre as garotas ultimamente?\n\"A lua cheia é um bom presságio.\" Espero que isso se aplique a nós também.",
  ui_story_5027_50270101_6_dialog_content = "Isso é apenas superstição. No entanto, tenho certeza de uma coisa.\nNão podemos ficar parados vendo pessoas sendo constantemente assediadas por bandidos.",
  ui_story_5027_50270101_7_dialog_content = "Você tem razão. Essa é a única razão pela qual precisamos.\nDesculpe por ter hesitado... É só que a missão desta vez é um pouco difícil—Hein?",
  ui_story_5027_50270101_8_dialog_content = "O que foi?",
