  ui_story_5027_50270101_21_dialog_content = "O que é isso?!",
  ui_story_5027_50270101_22_dialog_content = "Eles parecem hostis, mas por que é que...\nSeus ataques são totalmente diferentes de Eclipsitas e Aurorianos, e eu não consigo sentir nenhuma malícia neles?",
  ui_story_5027_50270101_23_dialog_content = "Eu não vi os poderes como o seu antes.\nPensar que os bandidos possuem esse tipo de força... Agora eu realmente não posso deixar você ir. Algemas! Desbloqueie!",
  ui_story_5027_50270101_24_dialog_content = "PESSOA!",
  ui_story_5027_50270101_25_dialog_content = "O que!? Essa é a outra presença que senti vindo deles!",
  ui_story_5027_50270101_26_dialog_content = "Impressionante...",
  ui_story_5027_50270101_27_dialog_content = "Os bandidos deveriam ser tão bons em lutar?",
  ui_story_5027_50270101_28_dialog_content = "Bandidos...? Eu vejo o que está acontecendo agora!",
  ui_story_5027_50270101_29_dialog_content = "Coringa, fique quieto. Eles nos confundem com outra pessoa.",
  ui_story_5027_50270101_30_dialog_content = "Quer dizer, é um mal-entendido?",
  ui_story_5027_50270101_31_dialog_content = "Luke, é o que eu acho também.\nA julgar pelo que aconteceu... acho que podemos conversar com eles.",
  ui_story_5027_50270101_32_dialog_content = "Toe-Kio...? Nunca ouvi falar de um lugar assim!",
  ui_story_5027_50270101_33_dialog_content = "Aurorianos, Eclipsitas, Colossos... e Umbraton...",
  ui_story_5027_50270101_34_dialog_content = "Seus nomes são Coringa e Rainha. Isso está certo?",
  ui_story_5027_50270101_35_dialog_content = "Então, se você está falando a verdade...\nSignifica que você chegou aqui de outro mundo?",
  ui_story_5027_50270101_36_dialog_content = "Tudo o que sabemos é que esta não é a nossa \"realidade\", a julgar pelas nossas roupas.",
  ui_story_5027_50270101_37_dialog_content = "Você disse algo sobre coisas que precisava fazer... Então você não está aqui por vontade própria?",
  ui_story_5027_50270101_38_dialog_content = "Sim, então precisamos voltar ao nosso mundo.",
  ui_story_5027_50270101_39_dialog_content = "Isso está além do que posso digerir... mas vamos ter que pausar essa conversa por enquanto.\nLuke, as coisas que senti antes fora dos subúrbios estão em movimento.",
  ui_story_5027_50270101_40_dialog_content = "Então... os bandidos do mal provavelmente estão em movimento.\nSe perdermos esta oportunidade, teremos que gastar muito tempo caçando-os novamente...",
  ui_story_5027_50270101_41_dialog_content = "Você pode sentir o que está acontecendo à distância...?",
  ui_story_5027_50270101_42_dialog_content = "Rainha, Coringa, entendemos que vocês não são nossos inimigos.\nMas sinto muito, não temos tempo para ajudá-lo agora... Precisamos voltar para nossa missão.\nNós precisamos ir, PlayerName!",
  ui_story_5027_50270101_43_dialog_content = "Espere. Então, antes, você pensou que éramos um dos bandidos?",
  ui_story_5027_50270101_44_dialog_content = "Você pode elaborar? Já que tecnicamente também somos vítimas deles, por assim dizer.",
