  ui_story_5027_50270101_46_dialog_content = "Sim. Coringa, Rainha, desculpe por isso, realmente.",
  ui_story_5027_50270101_47_dialog_content = "Lamentamos também, por retaliar fisicamente.",
  ui_story_5027_50270101_48_dialog_content = "Deixe-me explicar, então. Estamos tentando rastrear um grupo de bandidos que estão aterrorizando Umbraton.",
  ui_story_5027_50270101_49_dialog_content = "Depois de muita investigação, finalmente localizamos sua base de operações.\nOs Mercenários da Chama Branca iriam lançar um ataque surpresa esta noite.",
  ui_story_5027_50270101_50_dialog_content = "Porém, tivemos alguns problemas...",
  ui_story_5027_50270101_51_dialog_content = "Problemas?",
  ui_story_5027_50270101_52_dialog_content = "Eles sequestraram um menino e o mantêm prisioneiro.\nSe lançarmos um ataque completo, podemos colocá-lo em perigo.",
  ui_story_5027_50270101_53_dialog_content = "Ele ficou órfão em tenra idade... e agora, os bandidos até tiraram sua casa.",
  ui_story_5027_50270101_54_dialog_content = "Casa...",
  ui_story_5027_50270101_55_dialog_content = "Precisamos resgatá-lo e acabar com os bandidos ao mesmo tempo. Mas não é uma tarefa fácil.",
  ui_story_5027_50270101_56_dialog_content = "Por que você não se infiltra na base e rouba - quero dizer, resgatá-lo, antes de atacar os bandidos?",
  ui_story_5027_50270101_57_dialog_content = "Parece fácil, mas sua base é quase impenetrável...",
  ui_story_5027_50270101_58_dialog_content = "Pedaco de bolo. Afinal, somos os Phantom Thieves of Hearts.",
  ui_story_5027_50270101_59_dialog_content = "Ladrões fantasmas...? É isso que eu acho que é?",
  ui_story_5027_50270101_60_dialog_content = "Como ladrões que roubam os ímpios para ajudar os pobres?",
  ui_story_5027_50270101_61_dialog_content = "O tempo é essencial. Vamos sair primeiro, e contaremos tudo sobre nós no caminho.",
  ui_story_5027_50270101_62_dialog_content = "Você tem certeza disso? Este grupo de bandidos é bastante cruel.\nDepois de se envolver, encontrar um caminho de volta ao seu mundo não será seu único problema...",
  ui_story_5027_50270101_63_dialog_content = "Eu vou encontrar o caminho de volta.",
  ui_story_5027_50270101_64_dialog_content = "Mas não posso ficar parado e testemunhar o sofrimento das pessoas.",
  ui_story_5027_50270101_65_dialog_content = "Eu sabia que você ia dizer isso, Coringa.",
  ui_story_5027_50270101_66_dialog_content = "Não pode ficar parado, né?",
  ui_story_5027_50270101_67_dialog_content = "Soa como palavras saindo da boca de uma certa pessoa, certo?",
  ui_story_5027_50270101_68_dialog_content = "Coringa, Rainha, como Vice-Comandante dos Mercenários da Chama Branca...\nGostaria de contar com sua ajuda para derrubar os bandidos.",
  ui_story_5027_50270101_69_dialog_content = "Não há necessidade de ser tão formal. Nossos interesses estão alinhados. Chamaremos isso de comércio.",
  ui_story_5027_50270101_70_dialog_content = "Um comércio... Certo. Então, é um acordo?",
  ui_story_5027_50270101_71_dialog_content = "Sim. Agora, PlayerName, Luke, por que você não nos leva para a base dos bandidos?",
  ui_story_5027_50270101_72_dialog_content = "Então é aqui que os bandidos estão se escondendo... Que coisa artística.\nAposto que Fox gostaria de esboçá-lo se estivesse aqui.",
  ui_story_5027_50270101_73_dialog_content = "A presença dessas coisas é ainda mais proeminente aqui.\nO que não entendo, porém, é por que também sinto uma aura de tristeza misturada com a maldade dos bandidos.",
  ui_story_5027_50270101_74_dialog_content = "Deve ser o rapaz capturado, Barr. Essa tristeza deve estar vindo dele.",
  ui_story_5027_50270101_75_dialog_content = "Então qual é o plano?",
  ui_story_5027_50270101_76_dialog_content = "Os bandidos geralmente pensam da mesma forma. Escondem o que não querem que lhes seja roubado nos lugares mais profundos.",
  ui_story_5027_50270101_77_dialog_content = "Como temos uma localização geral e PlayerNamehabilidade psíquica de, tenho certeza de que poderemos encontrá-lo em breve.",
  ui_story_5027_50270101_78_dialog_content = "Então é assim que os Phantom Thieves funcionam? Impressionante.",
  ui_story_5027_50270101_79_dialog_content = "Bem, eu sou o tático da equipe.",
  ui_story_5027_50270101_80_dialog_content = "Estou começando a me sentir feliz por estarmos do mesmo lado.",
  ui_story_5027_50270101_81_dialog_content = "Vamos sair. Barr está esperando por nós.",
  ui_story_5027_50270201_1_dialog_content = "A julgar pela rota que percorremos e pelas estruturas ao nosso redor, deveríamos estar nos aproximando do coração deste lugar.",
  ui_story_5027_50270201_2_dialog_content = "A rainha está certa. Eu posso sentir a tristeza vindo daquele quarto à frente.",
  ui_story_5027_50270201_3_dialog_content = "E permanecemos desconhecidos. Tudo está indo bem.",
  ui_story_5027_50270201_4_dialog_content = "A propósito, aquela sala... parece ser onde eles escondem seus tesouros.",
  ui_story_5027_50270201_5_dialog_content = "Está trancado.",
  ui_story_5027_50270201_6_dialog_content = "Olhar. Há um mecanismo suspeito no teto.",
  ui_story_5027_50270201_7_dialog_content = "Esta altura... Ha!",
  ui_story_5027_50270201_8_dialog_content = "Ele pode alcançá-lo apenas pulando!?",
  ui_story_5027_50270201_9_dialog_content = "O Coringa é tão ágil quanto Violet.",
  ui_story_5027_50270201_10_dialog_content = "Lá. A porta está destrancada. Vamos entrar.",
  ui_story_5027_50270201_11_dialog_content = "Não há muito aqui para uma sala do tesouro.",
  ui_story_5027_50270201_12_dialog_content = "Eles provavelmente nunca planejaram ficar muito tempo em um lugar. Talvez eles já mudaram de base?",
  ui_story_5027_50270201_13_dialog_content = "Tem alguém dentro. Olhar. Lá, onde o luar derrama de cima...",
  ui_story_5027_50270201_14_dialog_content = "Vamos verificar.",
  ui_story_5027_50270201_15_dialog_content = "...!",
  ui_story_5027_50270201_16_dialog_content = "Eu sinto muito! Eu cochilei! Já volto ao trabalho!",
  ui_story_5027_50270201_17_dialog_content = "Parece que ele não foi tratado com humanidade.",
  ui_story_5027_50270201_18_dialog_content = "Há hematomas por todo o corpo.",
  ui_story_5027_50270201_19_dialog_content = "Isso é exatamente o que eu senti fora da base de bandidos.\nNão pensei que uma criança pudesse carregar um desespero tão pesado...",
  ui_story_5027_50270201_20_dialog_content = "Quem são vocês?",
  ui_story_5027_50270201_21_dialog_content = "Você deve ser Barr. Nós... não importa isso. Vamos tirar você daqui primeiro.",
  ui_story_5027_50270201_22_dialog_content = "Eu... Não. Eu não vou sair...",
  ui_story_5027_50270201_23_dialog_content = "Do que você está falando?",
  ui_story_5027_50270201_24_dialog_content = "Eles vão me capturar de novo, de qualquer maneira... E então eu vou ser espancado...\nTalvez seja melhor ficar aqui.",
  ui_story_5027_50270201_25_dialog_content = "Isso...",
  ui_story_5027_50270201_26_dialog_content = "Nossos inimigos estão em cima de nós.",
  ui_story_5027_50270201_27_dialog_content = "Coringa, por favor, cuide de Barr. Nós vamos comprar-lhe algum tempo!",
  ui_story_5027_50270201_28_dialog_content = "M-Mas... ele nem quer ir embora...",
