  ui_story_5027_50270201_34_dialog_content = "Ahn???",
  ui_story_5027_50270201_35_dialog_content = "Haha... Você é uma pessoa interessante.",
  ui_story_5027_50270201_36_dialog_content = "Você não quer sua liberdade?",
  ui_story_5027_50270201_37_dialog_content = "Claro que sim, mas...",
  ui_story_5027_50270201_38_dialog_content = [[
Quando eles ainda estavam vivos, meus pais me disseram uma vez...
