  ui_story_5027_50270201_39_dialog_content = "Então... eu tenho feito desejos... de ter minha liberdade de volta... mas...",
  ui_story_5027_50270201_40_dialog_content = "Então seu desejo se tornará realidade esta noite.",
  ui_story_5027_50270201_41_dialog_content = "O quê...?",
  ui_story_5027_50270201_42_dialog_content = "Nós somos os Ladrões Fantasmas. Estamos aqui para te roubar.",
  ui_story_5027_50270201_43_dialog_content = "Oh! Eu li sobre vocês nas histórias!",
  ui_story_5027_50270201_44_dialog_content = "Encontramos vocês, intrusos!",
