  ui_story_5027_50270201_48_dialog_content = "Diga-me onde está.",
  ui_story_5027_50270201_49_dialog_content = "Me siga!",
  ui_story_5027_50270201_50_dialog_content = "Aaaah!",
  ui_story_5027_50270201_51_dialog_content = "E-Eles são muito fortes...!",
  ui_story_5027_50270201_52_dialog_content = "Você é o único que resta agora. Infelizmente, você está condenado.",
  ui_story_5027_50270201_53_dialog_content = "Desistir. É inútil você resistir.",
  ui_story_5027_50270201_54_dialog_content = "Hahaha! Então vocês são os tolos que se atrevem a invadir a base de Rucker.",
  ui_story_5027_50270201_55_dialog_content = "B-Chefe...! Ahhh!",
  ui_story_5027_50270201_56_dialog_content = "Tá todo mundo bem?",
  ui_story_5027_50270201_57_dialog_content = "Palhaço!",
  ui_story_5027_50270201_58_dialog_content = "...!",
  ui_story_5027_50270201_59_dialog_content = "Barr? Parece que você chegou até ele.\nCuidamos de todos do nosso lado, exceto do líder.",
  ui_story_5027_50270201_60_dialog_content = "Então vocês estavam atrás do garoto? Haha ... eu tenho que entregar a vocês!",
  ui_story_5027_50270201_61_dialog_content = "Como assim?",
  ui_story_5027_50270201_62_dialog_content = "Bem, quero dizer, vocês estão prestes a jogar suas vidas fora—\nTudo por um pequeno nanico que só serve para trabalhos forçados! Hahahaha!",
  ui_story_5027_50270201_63_dialog_content = "Uma gaiola caiu do teto!?",
  ui_story_5027_50270201_64_dialog_content = "É uma armadilha!",
  ui_story_5027_50270201_65_dialog_content = "É tarde demais!",
  ui_story_5027_50270201_66_dialog_content = "Bar, corre!",
  ui_story_5027_50270201_67_dialog_content = "Ahhh!",
  ui_story_5027_50270201_68_dialog_content = "Vocês caras...!",
  ui_story_5027_50270201_69_dialog_content = "Ah, eu perdi um? Bem, isso não é nada para se preocupar.",
  ui_story_5027_50270201_70_dialog_content = "O que um nanico inútil pode fazer?\nHa, o que há com esse olhar em seu rosto, Barr?\nQuer tentar tirar essa chave de mim?",
  ui_story_5027_50270201_71_dialog_content = "E-se eu conseguir essa chave, posso salvá-los...",
  ui_story_5027_50270201_72_dialog_content = "Barr, apenas corra!",
  ui_story_5027_50270201_73_dialog_content = "Ahn???",
  ui_story_5027_50270201_74_dialog_content = "Apenas corra! Apenas salve-se!",
  ui_story_5027_50270201_75_dialog_content = "Não se preocupe conosco!",
  ui_story_5027_50270201_76_dialog_content = "Eu...",
  ui_story_5027_50270201_77_dialog_content = "Você quer liberdade, não é?",
  ui_story_5027_50270201_78_dialog_content = "Liberdade...",
  ui_story_5027_50270201_79_dialog_content = "Oh, que emoção, estou quase derramando lágrimas aqui.\nVou massacrar aquele garoto e curtir o som do seu choro!\nHahahaha!",
  ui_story_5027_50270201_80_dialog_content = "*Soluço*",
  ui_story_5027_50270201_81_dialog_content = [[
Eu sempre ia te matar mais cedo ou mais tarde...
Pode ser hoje. Barr, diga oi para seus pais por mim, sim?]],
  ui_story_5027_50270201_82_dialog_content = "Oh droga! Se isso continuar...",
  ui_story_5027_50270201_83_dialog_content = "E-Mesmo alguém como eu... pode... AHHHHH!",
  ui_story_5027_50270201_84_dialog_content = "Eca! O que diabos você pensa que está fazendo?! Eu vou te ensinar uma lição, verme!",
  ui_story_5027_50270201_85_dialog_content = "T-A chave! Agora... eu posso desbloquear o...",
  ui_story_5027_50270201_86_dialog_content = "Pelo menos, é hora de brincar.",
  ui_story_5027_50270201_87_dialog_content = "Obrigado, Barr.",
  ui_story_5027_50270201_88_dialog_content = "Agora o jogo virou!",
  ui_story_5027_50270201_89_dialog_content = "Porcaria!",
  ui_story_5027_50270201_90_dialog_content = "Agora — Xeque-mate.",
  ui_story_5027_50270201_91_dialog_content = "Eu... faz tanto tempo que não sinto o gosto do ar de fora...",
  ui_story_5027_50270201_92_dialog_content = "Mandei uma mensagem ao meu povo para cuidar das coisas aqui. Não se preocupe, este é o fim para os bandidos.",
  ui_story_5027_50270201_93_dialog_content = "Rucker se foi. É apenas uma questão de tempo antes de limparmos os retardatários que escaparam.",
  ui_story_5027_50270201_94_dialog_content = "Obrigado... Obrigado a todos por me salvarem!",
  ui_story_5027_50270201_95_dialog_content = "Então, Coringa, como você o convenceu?",
  ui_story_5027_50270201_96_dialog_content = "Sim, eu estive me perguntando o que deu a ele a força para enfrentar Rucker.",
  ui_story_5027_50270201_97_dialog_content = "Ele é como uma pessoa completamente diferente daquela que conhecemos.",
  ui_story_5027_50270201_98_dialog_content = "Eu não fiz nada. Barr decidiu por si mesmo que era hora de enfrentar Rucker.",
  ui_story_5027_50270201_99_dialog_content = "Ei, veja só... A lua está linda esta noite!",
  ui_story_5027_50270201_100_dialog_content = "De fato...",
  ui_story_5027_50270201_101_dialog_content = "A visão realmente levanta os ânimos, não é?",
  ui_story_5027_50270201_102_dialog_content = "Eu... Na verdade... Um pensamento me veio quando vi todos vocês sendo capturados.",
  ui_story_5027_50270201_103_dialog_content = "Já li quadrinhos sobre ladrões que ajudam os fracos. Eles lutam pelo que acreditam.\nEntão... eu pensei, talvez eu pudesse fazer isso também, lutar pela liberdade de todos!",
  ui_story_5027_50270201_104_dialog_content = "Foi assim que encontrei força em mim, eu acho... E você, você disse...",
  ui_story_5027_50270201_105_dialog_content = "Coringa e Rainha se foram...",
  ui_story_5027_50270201_106_dialog_content = "Para onde eles foram?",
  ui_story_5027_50270201_107_dialog_content = "Há lua cheia esta noite, Barr. Seu desejo se tornou realidade.",
  ui_story_5027_50270201_108_dialog_content = "Meu desejo...?",
  ui_story_5027_50270201_109_dialog_content = "Você desejou que todos nós fôssemos livres, não é?",
  ui_story_5027_50270201_110_dialog_content = "Então talvez seja isso que aconteceu com eles também.|\nTalvez sua partida seja o meio para sua liberdade."
